#!/usr/bin/env python3
"""Recursive, byte-oriented text searching with an ag-compatible CLI.

The traversal, option handling and result renderer are independent.  PCRE is
used as a generic regular-expression engine; all application logic lives here.
"""
import os
import sys
import stat
import re
import ctypes
import ctypes.util
import fnmatch
import bisect
import time
import gzip
import lzma
from dataclasses import dataclass, field
from interface import HELP, VERSION, TYPE_HELP, FILE_TYPES


def b(s):
    return os.fsencode(s)


def out(s):
    sys.stdout.buffer.write(s if isinstance(s, bytes) else b(s))


class RegexError(Exception):
    def __init__(self, pos, message):
        self.pos, self.message = pos, message


class Regex:
    """Small binding to the system's general-purpose PCRE library."""
    lib = None
    initialized = False

    @classmethod
    def initialize(cls):
        if cls.initialized:
            return
        cls.initialized = True
        try:
            cls.lib = ctypes.CDLL('libpcre.so.3')
        except OSError:
            try:
                cls.lib = ctypes.CDLL(ctypes.util.find_library('pcre'))
            except (OSError, TypeError):
                cls.lib = None
        if cls.lib:
            cls.lib.pcre_compile.argtypes = [ctypes.c_char_p, ctypes.c_int,
                ctypes.POINTER(ctypes.c_char_p), ctypes.POINTER(ctypes.c_int), ctypes.c_void_p]
            cls.lib.pcre_compile.restype = ctypes.c_void_p
            cls.lib.pcre_exec.argtypes = [ctypes.c_void_p, ctypes.c_void_p,
                ctypes.c_char_p, ctypes.c_int, ctypes.c_int, ctypes.c_int,
                ctypes.POINTER(ctypes.c_int), ctypes.c_int]
            cls.lib.pcre_exec.restype = ctypes.c_int

    def __init__(self, pattern, ignorecase=False):
        Regex.initialize()
        self.pattern = pattern
        if self.lib:
            err, pos = ctypes.c_char_p(), ctypes.c_int()
            self.code = self.lib.pcre_compile(pattern, 2 | int(ignorecase), ctypes.byref(err), ctypes.byref(pos), None)
            if not self.code:
                raise RegexError(pos.value, err.value.decode('utf-8', 'replace'))
            self.ov = (ctypes.c_int * 300)()
        else:
            try:
                self.code = re.compile(pattern, re.M | (re.I if ignorecase else 0))
            except re.error as e:
                raise RegexError(e.pos or 0, str(e).split(' at position')[0])

    def search(self, data, start=0):
        if self.lib:
            rc = self.lib.pcre_exec(self.code, None, data, len(data), start, 0, self.ov, len(self.ov))
            if rc < 0:
                return None
            return self.ov[0], self.ov[1]
        m = self.code.search(data, start)
        return m.span() if m else None


@dataclass
class Options:
    case: str = 'smart'
