def atoi(s):
    m = re.match(r'\s*[+-]?\d+', s or '')
    return int(m[0]) if m else 0


def parse_options(argv):
    o = Options(color=sys.stdout.isatty(), group=sys.stdout.isatty())
    def fail(message):
        sys.stderr.buffer.write(b(sys.argv[0] + ': ' + message + '\n'))
        out(HELP)
        raise SystemExit(1)

    def apply(name, arg=None):
        if name == 'help':
            out(HELP); raise SystemExit(0)
        if name == 'version':
            out(VERSION); raise SystemExit(0)
        if name == 'list-file-types':
            out(TYPE_HELP); raise SystemExit(0)
        if name in FILE_TYPES:
            o.types.extend(FILE_TYPES[name]); return
        if name == 'ackmate': o.ackmate = True; o.parallel = True
        elif name == 'vimgrep': o.vimgrep = True; o.parallel = True
        elif name == 'ackmate-dir-filter': o.dir_filter = arg
        elif name == 'heading': o.path_mode = 'top'
        elif name == 'noheading': o.path_mode = 'each'
        elif name == 'filename': o.path_mode = 'default'; o.numbers = 2
        elif name == 'nofilename': o.path_mode = 'none'; o.numbers = 0
        elif name == 'numbers': o.numbers = 1
        elif name == 'nonumbers': o.numbers = 0
        elif name == 'color-line-number': o.color_number = b(arg)
        elif name == 'color-path': o.color_path = b(arg)
        elif name == 'color-match': o.color_match = b(arg)
        elif name == 'files-with-matches': o.list_match = True; o.path_mode = 'top'
        elif name == 'files-without-matches': o.list_without = True; o.path_mode = 'top'
        elif name == 'filename-pattern': o.filename_pattern = arg
        elif name == 'file-search-regex': o.file_regex = arg
        elif name in ('fixed-strings','literal'): o.literal = True
        elif name == 'word-regexp': o.word = True
        elif name == 'case-sensitive': o.case = 'sensitive'
        elif name == 'ignore-case': o.case = 'ignore'
        elif name == 'smart-case': o.case = 'smart'
        elif name in ('after','before','context'):
            n = 2 if arg is None else atoi(arg)
            if name in ('before','context'): o.before = n
            if name in ('after','context'): o.after = n
        elif name == 'max-count': o.max_count = atoi(arg)
        elif name == 'depth': o.depth = atoi(arg)
        elif name == 'workers': o.workers = atoi(arg)
        elif name == 'width':
            if not re.fullmatch(r'\s*[+-]?\d+', arg or ''):
                o.err('Invalid width\n'); raise SystemExit(2)
            o.width = int(arg)
        elif name in ('ignore','ignore-dir'): o.ignores.append(arg)
        elif name == 'path-to-ignore': o.ignore_files.append(arg)
        elif name == 'pager': o.pager = arg
        elif name == 'nopager': o.pager = ''
        elif name in ('all-types','unrestricted','all-text'):
            o.all_files = True
            if name != 'all-text': o.binary = True
            if name == 'unrestricted': o.hidden = True
        elif name == 'stats-only': o.stats = True; o.stats_only = True
        else:
            mapping = {'break':('breaks',True), 'nobreak':('breaks',False),
                'group':('group',True), 'nogroup':('group',False),
                'color':('color',True), 'nocolor':('color',False),
                'follow':('follow',True), 'nofollow':('follow',False),
                'mmap':('mmap',True), 'nommap':('mmap',False),
                'affinity':('affinity',True), 'noaffinity':('affinity',False),
                'recurse':('recurse',True), 'norecurse':('recurse',False),
                'multiline':('multiline',True), 'nomultiline':('multiline',False),
                'column':('column',True), 'count':('count',True),
                'only-matching':('only',True), 'hidden':('hidden',True),
                'invert-match':('invert',True), 'search-binary':('binary',True),
                'search-zip':('compressed',True), 'skip-vcs-ignores':('skip_vcs',True),
                'one-device':('one_device',True), 'parallel':('parallel',True),
                'print-all-files':('print_all',True), 'print-long-lines':('print_long',True),
                'passthrough':('passthrough',True), 'passthru':('passthrough',True),
                'stats':('stats',True), 'silent':('silent',True), 'debug':('debug',True),
                'null':('null',True), 'print0':('null',True)}
            if name in mapping:
                attr, val = mapping[name]; setattr(o, attr, val)

    if not argv:
        out(HELP); raise SystemExit(1)
    positional = []
    i = 0
    while i < len(argv):
        a = argv[i]
        i += 1
        if a == '--':
            positional.extend(argv[i:]); break
        if a.startswith('--'):
            name, eq, val = a[2:].partition('=')
            all_names = list(LONG_OPTIONS) + list(FILE_TYPES)
            if name not in all_names:
                names = [k for k in all_names if k.startswith(name)]
                if not names:
                    fail("unrecognized option '"+a+"'")
                if len(names) > 1:
                    fail("option '"+a+"' is ambiguous; possibilities:"+''.join(" '--"+n+"'" for n in names))
                name = names[0]
            kind = LONG_OPTIONS.get(name, 0)
            if kind == 0 and eq:
                fail("option '--"+name+"' doesn't allow an argument")
            value = val if eq else None
            if kind == 1 and value is None:
                if i >= len(argv): fail("option '"+a+"' requires an argument")
                value = argv[i]; i += 1
            if kind == 2 and value is None and i < len(argv) and re.fullmatch(r'-?\d+', argv[i]):
                value = argv[i]; i += 1
            apply(name,value)
        elif a.startswith('-') and a != '-':
            j = 1
            while j < len(a):
                c = a[j]; j += 1
                if c not in SHORT_OPTIONS: fail("invalid option -- '"+c+"'")
                name = SHORT_OPTIONS[c]; kind = LONG_OPTIONS[name]; value = None
                if kind:
                    if j < len(a): value = a[j:]; j = len(a)
                    elif kind == 1:
                        if i >= len(argv): fail("option requires an argument -- '"+c+"'")
                        value = argv[i]; i += 1
                    elif i < len(argv) and re.fullmatch(r'-?\d+', argv[i]):
                        value = argv[i]; i += 1
                apply(name,value)
        else:
            positional.append(a)
            if os.environ.get('POSIXLY_CORRECT'):
                positional.extend(argv[i:]); break
    if o.filename_pattern is not None:
        o.query = b'.'; o.paths = positional
    elif positional:
        o.query = b(positional[0]); o.paths = positional[1:]
    elif o.list_match:
        o.query = b'.'
    else:
        o.err('What do you want to search for?'); raise SystemExit(1)
    if not o.query:
        if o.list_match: o.query = b'.'
        else:
            o.err('Error: No query. What do you want to search for?'); raise SystemExit(1)
    try:
        mode = os.fstat(0).st_mode
        o.input_stream = (stat.S_ISREG(mode) or stat.S_ISFIFO(mode)) and not o.parallel
    except OSError:
        pass
    o.actual_stream = o.input_stream and not o.paths
    if not o.paths and not o.actual_stream: o.paths = ['.']
    o.single_file = len(o.paths)==1 and os.path.isfile(o.paths[0])
    if o.input_stream:
        o.path_mode = 'none'; o.breaks = False
        if o.numbers == 2: o.numbers = 0
    if o.path_mode == 'default':
        if o.single_file:
            o.path_mode = 'none'
        elif o.group or o.ackmate:
            o.path_mode = 'top'
        else:
            o.path_mode = 'each'; o.breaks = False
    if o.only and o.path_mode == 'none': o.numbers = 0
    if o.numbers == 2: o.numbers = 1
    if o.ackmate:
        o.color = False; o.numbers = 1
    if o.vimgrep:
        o.color = False; o.numbers = 1; o.column = True; o.breaks = False; o.path_mode = 'each'
    if not o.recurse: o.depth = 0
    return o


def is_binary(data):
    sample = data[:512]
    if b'\0' in sample: return True
    if sample.startswith(b'%PDF-'): return True
    bad = 0
    i = 0
    while i < len(sample):
        c = sample[i]
        if c in (8,9,10,12,13,27) or 32 <= c <= 126:
            i += 1; continue
        if c >= 194:
            length = 2 if c <= 223 else 3 if c <= 239 else 4 if c <= 244 else 0
            if length and all(128 <= x <= 191 for x in sample[i+1:i+length]) and len(sample[i:i+length]) == length:
                i += length; continue
        bad += 1; i += 1
    return bad > len(sample) / 10


class Matcher:
    def __init__(self, o):
        self.o = o
        self.query = o.query
        self.all = self.query == b'.' and not o.literal and not o.word
        self.literal = o.literal or not any(c in b'\\^$.*+?()[]{}|' for c in self.query)
        self.icase = o.case == 'ignore' or (o.case == 'smart' and not re.search(b'[A-Z]', self.query))
        self.rx = None
        if o.word or not self.literal and not self.all:
            q = re.escape(self.query) if self.literal else self.query
            if o.word: q = b'\\b(?:' + q + b')\\b'
            self.rx = Regex(q, self.icase)
        self.needle = self.query.lower() if self.icase else self.query

    def _scan(self, data):
        if self.all:
            if data: yield 0, len(data)
            return
        pos = 0
        d = data.lower() if self.literal and not self.rx and self.icase else data
        while pos < len(data):
            if self.rx:
                hit = self.rx.search(data, pos)
                if hit is None: break
                start, end = hit
            else:
                start = d.find(self.needle, pos)
                if start < 0: break
                end = start + len(self.needle)
            yield start, end
            pos = max(end, start + 1)

    def find(self, data, path):
        o = self.o
        matches = []
        if not o.multiline and self.rx:
            def lines():
                off = 0
                for line in data.splitlines(keepends=True):
                    line = line[:-1] if line.endswith(b'\n') else line
                    for a,z in self._scan(line): yield a+off,z+off
                    off += len(line)+1
            scan = lines()
        else:
            scan = self._scan(data)
        for m in scan:
            matches.append(m)
            if o.max_count > 0 and len(matches) >= o.max_count:
                o.err('Too many matches in ' + path + '. Skipping the rest of this file.')
                break
        return matches


@dataclass
class IgnoreRule:
    root: str
    pattern: str
    negated: bool = False
    dir_only: bool = False
    anchored: bool = False

    def match(self, path, directory):
        rel = os.path.relpath(path,self.root).replace(os.sep,'/')
        if rel.startswith('../'): return False
        p = self.pattern
        if self.dir_only and not directory: return False
        if '/' not in p and not self.anchored:
            return fnmatch.fnmatchcase(os.path.basename(path), p)
        # fnmatch with pathname semantics and the git-style ** operator.
        return glob_path(p, rel)


def glob_path(pattern, path):
    pp, ss = pattern.split('/'), path.split('/')
    def match(i,j):
        if i==len(pp): return j==len(ss)
        if pp[i]=='**':
            return match(i+1,j) or j<len(ss) and match(i,j+1)
        return j<len(ss) and fnmatch.fnmatchcase(ss[j],pp[i]) and match(i+1,j+1)
    return match(0,0)


def rules_from_lines(lines, root):
    rules=[]
    for line in lines:
        line=line.rstrip('\r\n')
        if not line or line.startswith('#'): continue
        # Escaped whitespace and comment markers are literal filename bytes.
        line=line.rstrip(' ')
        if not line: continue
        negate=line.startswith('!')
        if negate: line=line[1:]
        anchor=line.startswith('/')
        if anchor: line=line[1:]
        onlydir=line.endswith('/')
        if onlydir: line=line[:-1]
        line=line.replace('\\ ', ' ').replace('\\#','#').replace('\\!', '!')
        rules.append(IgnoreRule(root,line,negate,onlydir,anchor))
    return rules


class Walker:
    def __init__(self, o):
        self.o=o
        self.global_rules=[]
        self.seen=set()
        self.frx = None
        for pattern in (o.filename_pattern,o.file_regex):
            if pattern is not None:
                self.frx = Regex(b(pattern), o.case=='ignore' or o.case=='smart' and not re.search('[A-Z]',pattern))
        self.drx = Regex(b(o.dir_filter)) if o.dir_filter else None
        if not o.all_files:
            root=os.path.abspath('.')
            self.global_rules.extend(rules_from_lines(o.ignores,root))
            self.load_file(os.path.expanduser('~/.agignore'),root,self.global_rules)
            for f in o.ignore_files: self.load_file(f,root,self.global_rules)

    @staticmethod
    def load_file(path, root, rules):
        try:
            with open(path,encoding='utf-8',errors='surrogateescape') as f:
                rules.extend(rules_from_lines(f,root))
        except OSError:
            pass

    def ignores_here(self, path, rules):
        rules=list(rules)
        if self.o.all_files: return rules
        paths=['.ignore']
        if not self.o.skip_vcs: paths += ['.gitignore','.git/info/exclude','.hgignore']
        for name in paths: self.load_file(os.path.join(path,name),os.path.abspath(path),rules)
        return rules

    def ignored(self,path,directory,rules):
        if self.o.all_files: return False
        ignored=False
        for r in rules:
            if r.match(os.path.abspath(path),directory): ignored=not r.negated
        return ignored

    def initial_rules(self,path):
        rules=list(self.global_rules)
        # Parent ignore files also apply when a nested search root is supplied.
        parent=os.path.dirname(os.path.abspath(path))
        ancestors=[]
        while True:
            ancestors.append(parent)
            up=os.path.dirname(parent)
            if up==parent:break
            parent=up
        for p in reversed(ancestors): rules=self.ignores_here(p,rules)
        return rules

    def file_allowed(self,path):
        if self.frx and self.frx.search(b(path)) is None:return False
        if self.o.types and not any(path.endswith(ext) for ext in self.o.types):return False
        return True

    def directory(self,path,depth,rules,device,chain):
        o=self.o
        try:
            st=os.stat(path)
            key=(st.st_dev,st.st_ino)
            if key in chain:
                o.err('Recursive directory loop: '+path); return
            chain=chain|{key}
            entries=list(os.scandir(path))
        except OSError as e:
            o.err('Error opening directory '+path+': '+e.strerror); return
        rules=self.ignores_here(path,rules)
        dirs=[]; files=[]
        for entry in entries:
            if not o.hidden and entry.name.startswith('.'):continue
            child=os.path.join(path,entry.name)
            try:
                if entry.is_symlink() and not o.follow:continue
                st=entry.stat(follow_symlinks=True)
            except OSError:continue
            directory=stat.S_ISDIR(st.st_mode)
            if self.ignored(child,directory,rules):continue
            if directory:
                if o.one_device and st.st_dev!=device:continue
                if self.drx and self.drx.search(b(child)) is None:continue
                dirs.append(child)
            elif stat.S_ISREG(st.st_mode) and self.file_allowed(child):files.append(child)
        for child in dirs:
            if o.depth<0 or depth<o.depth:
                yield from self.directory(child,depth+1,rules,device,chain)
        for child in files:yield child,True

    def walk(self):
        for path in self.o.paths:
            # A trailing slash on a directory is cosmetic, but preserve ./.
            if len(path)>1: path=path.rstrip('/') or '/'
            try: st=os.stat(path)
            except OSError:
                self.o.err('Error stat()ing: '+path)
                self.o.err('Error opening directory '+path+': No such file or directory')
                continue
            if stat.S_ISDIR(st.st_mode):
                yield from self.directory(path,0,self.initial_rules(path),st.st_dev,set())
            else:
                yield path,False


RESET = b'\x1b[0m\x1b[K'


class Renderer:
    def __init__(self,o):
        self.o=o
        self.did_output=False

    @staticmethod
    def display_path(path):
        if path.startswith('./'): path=path[2:]
        return b(path)

    def paint(self,text,code):
        return b'\x1b['+code+b'm'+text+RESET if self.o.color else text

    def path(self,path):
        return self.paint(self.display_path(path),self.o.color_path)

    def number(self,n):
        return self.paint(str(n).encode(),self.o.color_number)

    def prefix(self,path,num,col=None,context=False):
        o=self.o
        p=b''
        if o.path_mode=='each' and not o.vimgrep:
            p+=self.path(path)+b':'
        if o.numbers:
            p+=self.number(num)+(b':' if not context or o.ackmate or o.vimgrep else b'-')
        if col is not None and o.column and not context: p+=str(col).encode()+b':'
        return p

    def head(self,path):
        o=self.o
        result=b''
        if self.did_output and o.breaks and not o.input_stream:result+=b'\n'
        if o.path_mode=='top':
            if o.ackmate: result+=b':'
            result+=self.path(path)+(b'\0' if o.null else b'\n')
        self.did_output=True
        return result

    def list_file(self,path,count=None,force=False):
        o=self.o
        end=b'\0' if o.null else b'\n'
        result=b''
        if o.path_mode!='none':result=self.path(path)
        if count is not None:
            if result:result+=b':'
            result+=self.number(count)
        if result:
            self.did_output=True
            out(result+end)

    def format_content(self,data,a,z,hits):
        o=self.o
        limit=z
        truncated=o.width>0 and z-a>o.width
        if truncated:limit=a+o.width
        if not o.color:
            return data[a:limit]+(b' [...]' if truncated else b'')
        result=b''; p=a
        for x,y in hits:
            if y<=a and x!=y or x>limit:continue
            x=max(x,a);y=min(y,limit)
            if y<x:continue
            if x<p: x=p
            result+=data[p:x]
            if y>=x:
                result+=self.paint(data[x:y],o.color_match)
            p=y
        result+=data[p:limit]
        if truncated:result+=b' [...]'
        return result

    def render(self,path,data,matches,stream=False,base_line=0,context_mask=None):
        o=self.o
        starts=[0]+[i+1 for i,x in enumerate(data) if x==10]
        # A non-newline-terminated last line is a line; an empty terminal line
        # is shown only when a match itself crosses into it.
        nlines=len(starts) if data and not data.endswith(b'\n') else len(starts)-1
        line_matches={}
        for a,z in matches:
            first=bisect.bisect_right(starts,a)-1
            last=bisect.bisect_right(starts,z)-1
            for i in range(first,last+1):
                line_matches.setdefault(i,[]).append((a,z))
        if o.invert:
            chosen={i for i in range(nlines) if i not in line_matches}
        else:
            chosen=set(line_matches)
        contexts=set()
        for i in chosen:
            contexts.update(range(max(0,i-max(o.before,0)),min(nlines,i+max(o.after,0)+1)))
        contexts-=chosen
        if context_mask is not None: contexts=set(context_mask)-chosen
        lines=sorted(chosen|contexts)
        if not lines:
            return self.head(path) if o.print_all else b''
        result=self.head(path) if not stream else b''
        previous=None
        for i in lines:
            if i>=len(starts): continue
            a=starts[i]
            z=starts[i+1]-1 if i+1<len(starts) else len(data)
            if previous is not None and i>previous+1 and (o.before or o.after) and not stream:
                result+=b'--\n'
            previous=i
            context=i in contexts
            hits=line_matches.get(i,[])
            num=i+1+base_line
            col=(hits[0][0]-a+1 if hits and hits[0][0]>=a else 0) if not o.invert else 1
            if context:
                result+=self.prefix(path,num,context=True)+self.format_content(data,a,z,[])+b'\n'
                if z==len(data) and not stream: result+=b'\n'
                continue
            if o.ackmate:
                ending=[(x,y) for x,y in hits if y<=z]
                result+=str(num).encode()+b';'
                if ending:
                    result+=b','.join(str(max(0,x-a)).encode()+b' '+str(y-x).encode() for x,y in ending)+b':'
                result+=data[a:z]
                if z<len(data) or not stream:result+=b'\n'
                continue
            if o.vimgrep:
                for x,y in hits:
                    if y>z:continue
                    column=x-a+1 if x>=a else 0
                    result+=self.display_path(path)+b':'+str(num).encode()+b':'+str(column).encode()+b':'+self.format_content(data,a,z,[])+b'\n'
                continue
            if o.only:
                if o.invert:
                    part=data[a:z]
                    if z==len(data):part=part[:-1]
                    result+=self.prefix(path,num,1)+part+b'\n'
                else:
                    for x,y in hits:
                        if x<a:continue
                        part=data[x:y]
                        if o.width>0 and len(part)>o.width:part=part[:o.width]+b' [...]'
                        result+=self.prefix(path,num,x-a+1)+self.paint(part,o.color_match)+b'\n'
                continue
            if o.invert:
                hits=[(a,z)] if o.color else []
            result+=self.prefix(path,num,col)+self.format_content(data,a,z,hits)
            if z<len(data) or not stream and (z>a or not hits):result+=b'\n'
        if o.only and data and not data.endswith(b'\n') and lines and lines[-1]==nlines-1 and not stream:
            result+=b'\n'
        return result


class Application:
    def __init__(self,o):
        self.o=o
        self.matcher=Matcher(o)
        self.walker=Walker(o)
        self.renderer=Renderer(o)
        self.success=False
        self.total_matches=0
        self.total_files=0
        self.match_files=0
        self.total_bytes=0

    @staticmethod
    def inverted_count(data,matches):
        # Counts are contiguous ranges of nonmatching lines, rather than lines.
        starts=[0]+[i+1 for i,c in enumerate(data) if c==10]
        n=len(starts)-(1 if data.endswith(b'\n') else 0)
        bad=set()
        for a,z in matches:
            bad.update(range(bisect.bisect_right(starts,a)-1,bisect.bisect_right(starts,z)-1+1))
        return sum(1 for i in range(n) if i not in bad and (i==0 or i-1 in bad))

    def process_data(self,path,data,isbin=False,stream=False,base_line=0):
        o=self.o
        if not data:return False,[]
        matches=self.matcher.find(data,path)
        cnt=self.inverted_count(data,matches) if o.invert else len(matches)
        self.total_files+=1; self.total_bytes+=len(data); self.total_matches+=cnt
        if cnt:self.match_files+=1
        selected = not cnt if o.list_without else bool(cnt) or o.print_all
        if selected and not (stream and o.list_without):self.success=True
        if o.stats_only:return bool(cnt),matches
        if o.list_without:
            if not cnt and not stream:self.renderer.list_file(path)
            return bool(cnt),matches
        if not selected:return False,matches
        if o.count:
            self.renderer.list_file(path,cnt)
        elif o.list_match:
            self.renderer.list_file(path)
        elif isbin:
            out(b'Binary file '+self.renderer.display_path(path)+b' matches.\n')
        else:
            out(self.renderer.render(path,data,matches,stream,base_line))
        return bool(cnt),matches

    def search_stream(self, stream):
        o=self.o
        # A pipe is searched one line at a time, which also affects counts.
        before=[]
        after=0
        printed=-1
        for index,line in enumerate(stream):
            matches=self.matcher.find(line,'')
            cnt=self.inverted_count(line,matches) if o.invert else len(matches)
            self.total_files+=1;self.total_bytes+=len(line);self.total_matches+=cnt
            if cnt:self.match_files+=1
            if cnt and not o.list_without:self.success=True
            if o.print_all and not o.list_without:self.success=True
            if o.stats_only:continue
            if o.list_match or o.list_without or o.count:
                if cnt and not o.list_without:
                    if o.count:self.renderer.list_file('',cnt)
                continue
            if cnt:
                for n,old in before:
                    if n>printed:
                        out(self.renderer.prefix('',n+1,context=True)+old.rstrip(b'\n')+b'\n');printed=n
                out(self.renderer.render('',line,matches,True,index))
                printed=index; after=max(o.after,0)
            elif o.passthrough:
                out(line);printed=index
            elif after>0:
                out(self.renderer.prefix('',index+1,context=True)+line.rstrip(b'\n')+b'\n');after-=1;printed=index
            before.append((index,line))
            if len(before)>max(o.before,0):before=before[-max(o.before,0):] if o.before>0 else []

    def run(self):
        start=time.monotonic()
        o=self.o
        if o.actual_stream:
            self.search_stream(sys.stdin.buffer)
        else:
            for path,traversed in self.walker.walk():
                if traversed and o.filename_pattern is not None:
                    self.renderer.list_file(path)
                    self.success=True
                    continue
                try:
                    st=os.stat(path)
                    if not stat.S_ISREG(st.st_mode) and not stat.S_ISFIFO(st.st_mode):
