                if binary and not o.binary:continue
                self.process_data(path,data,binary)
        if o.stats:
            out(f'{self.total_matches} matches\n{self.match_files} files contained matches\n{self.total_files} files searched\n{self.total_bytes} bytes searched\n{time.monotonic()-start:.6f} seconds\n')
        return 0 if self.success else 1


def main():
    o=parse_options(sys.argv[1:])
    try:
        app=Application(o)
        return app.run()
    except RegexError as e:
        o.err(f'Bad regex! pcre_compile() failed at position {e.pos}: {e.message}\nIf you meant to search for a literal string, run ag with -Q')
        return 2


if __name__=='__main__':
    try:
        sys.exit(main())
    except BrokenPipeError:
        try:sys.stdout.close()
        except OSError:pass
        os._exit(0)
